//! [`Settings`]: every user preference, as one typed, versioned document.

use serde::{Deserialize, Serialize};

use super::{SettingsError, SettingsSection};

/// The settings format this build writes. Bump it, and add the upgrade to
/// [`Settings::upgraded`], when a change cannot be expressed by defaults.
pub const SETTINGS_VERSION: u32 = 1;

/// Declares [`Settings`] from the registered sections (the invocation is
/// generated by `build.rs` from every `register_section!`): the struct, its
/// `Default`, `validate` and the dialog-only paths of a patch.
macro_rules! settings {
    (
        sections: [$($(#[doc = $doc:literal])+ $key:ident: $($section:ident)::+,)+]
        dialog_only: [$(($in:literal, $field:literal, $path:literal),)*]
    ) => {
        /// Every user preference. Secrets are never here; they live in the Keychain.
        ///
        /// Each section, and each field in it, falls back to its default when the
        /// file lacks it, so adding a field never breaks an existing file.
        #[derive(Clone, Debug, PartialEq, Serialize, Deserialize, specta::Type)]
        #[serde(rename_all = "camelCase", default)]
        pub struct Settings {
            /// The format version; read-only for patches.
            pub version: u32,
            $($(#[doc = $doc])+ pub $key: $($section)::+,)+
        }

        impl Default for Settings {
            fn default() -> Self {
                Self {
                    version: SETTINGS_VERSION,
                    $($key: <$($section)::+>::default(),)+
                }
            }
        }

        impl Settings {
            /// Checks every rule a section enforces.
            pub fn validate(&self) -> Result<(), SettingsError> {
                $(SettingsSection::check(&self.$key)?;)+
                Ok(())
            }
        }

        /// Settings the UI may clear but never set, as (section, field,
        /// path), from each section's `dialog_only`: paths Deino writes to
        /// come only from dialogs Rust opens (EXP-02), and the API server's
        /// switch and port only from the `api` plugin (DEV-03).
        pub(super) const DIALOG_ONLY: &[(&str, &str, &str)] = &[$(($in, $field, $path),)*];
    };
}

include!(concat!(env!("OUT_DIR"), "/settings_model.rs"));

impl Settings {
    /// These settings in the current format.
    ///
    /// Version 1 is the first format, so there is nothing to convert yet. A
    /// file from a newer build keeps the fields this build knows.
    #[must_use]
    pub fn upgraded(mut self) -> Self {
        if self.version > SETTINGS_VERSION {
            log::warn!(
                target: "settings",
                "settings file is version {}, newer than {SETTINGS_VERSION}; unknown fields are dropped",
                self.version
            );
        }
        self.version = SETTINGS_VERSION;
        self
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn an_empty_file_is_the_defaults() {
        let settings: Settings = serde_json::from_str("{}").unwrap();
        assert_eq!(settings, Settings::default());
    }

    #[test]
    fn a_partial_section_keeps_the_other_defaults() {
        let settings: Settings =
            serde_json::from_str(r#"{ "ui": { "theme": "dark" }, "future": 1 }"#).unwrap();

        assert_eq!(settings.ui.theme, super::super::Theme::Dark);
        assert!(settings.ui.show_confidence_indicator);
        assert!(settings.recording.auto_save);
    }

    #[test]
    fn defaults_are_valid_and_current() {
        let settings = Settings::default();
        assert!(settings.validate().is_ok());
        assert_eq!(settings.version, SETTINGS_VERSION);
    }

    #[test]
    fn upgrading_stamps_the_current_version() {
        let old = Settings {
            version: 0,
            ..Settings::default()
        };
        assert_eq!(old.upgraded().version, SETTINGS_VERSION);
    }

    /// A `settings.json` with every section, written before REG-02
    /// generated `Settings` (non-default values throughout).
    const FULL_FILE: &str = include_str!("../../tests/fixtures/settings-full.json");

    /// Whether every field of `expected` is in `actual` with the same value.
    fn contains(actual: &serde_json::Value, expected: &serde_json::Value) -> bool {
        match (actual, expected) {
            (serde_json::Value::Object(actual), serde_json::Value::Object(expected)) => expected
                .iter()
                .all(|(key, value)| actual.get(key).is_some_and(|found| contains(found, value))),
            _ => actual == expected,
        }
    }

    /// The top-level keys of a pretty-printed document, in order.
    fn top_level_keys(pretty: &str) -> Vec<&str> {
        pretty
            .lines()
            .filter_map(|line| line.strip_prefix("  \""))
            .filter_map(|line| line.split_once('"').map(|(key, _)| key))
            .collect()
    }

    #[test]
    fn todays_full_settings_file_round_trips() {
        let settings: Settings = serde_json::from_str(FULL_FILE).unwrap();
        settings.validate().unwrap();
        let written = serde_json::to_string_pretty(&settings).unwrap() + "\n";

        let before: serde_json::Value = serde_json::from_str(FULL_FILE).unwrap();
        let after: serde_json::Value = serde_json::from_str(&written).unwrap();
        // Every value survives; a section added later may only add fields.
        assert!(contains(&after, &before), "a setting changed:\n{written}");
        let order: Vec<&str> = top_level_keys(&written)
            .into_iter()
            .filter(|key| before.get(key).is_some())
            .collect();
        assert_eq!(order, top_level_keys(FULL_FILE), "the sections moved");
    }

    #[test]
    fn the_sections_keep_their_place_in_the_file() {
        let written = serde_json::to_string_pretty(&Settings::default()).unwrap();
        let keys = top_level_keys(&written);

        assert_eq!(keys.first(), Some(&"version"));
        let known: Vec<&str> = keys
            .iter()
            .copied()
            .filter(|key| FULL_FILE.contains(&format!("\n  \"{key}\":")))
            .collect();
        assert_eq!(known, top_level_keys(FULL_FILE));
    }

    #[test]
    fn dialog_only_paths_come_from_the_sections() {
        assert_eq!(
            DIALOG_ONLY,
            &[
                ("export", "folder", "export.folder"),
                ("api", "enabled", "api.enabled"),
                ("api", "port", "api.port"),
            ]
        );
    }

    #[test]
    fn every_section_is_validated() {
        let mut settings = Settings::default();
        settings.api.port = 1;
        assert!(settings.validate().is_err());

        let mut settings = Settings::default();
        settings.ui.transcript_pane_ratio = 2.0;
        assert!(settings.validate().is_err());
    }
}
